SAFE_NAME = re.compile(r"^[A-Za-z0-9._-]{1,40}$")
HOST_OK = re.compile(r"^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$")   # an address or name, never an option
TOKEN_HEADER = "X-Studio-Token"

